<?php $billingRequest=null;$financialSummary=null;if($platform){$pdo=\App\Core\Database::connection();$br=$pdo->prepare('SELECT * FROM billing_support_requests WHERE ticket_id=:ticket LIMIT 1');$br->execute(['ticket'=>$ticket['id']]);$billingRequest=$br->fetch()?:null;if($billingRequest&&$billingRequest['request_type']==='account_deletion'){$fs=$pdo->prepare("SELECT (SELECT COUNT(*) FROM invoices WHERE tenant_id=:t AND status='overdue') overdue_invoices,(SELECT COUNT(*) FROM payments WHERE tenant_id=:t2 AND status='pending') pending_payments,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE tenant_id=:t3 AND status='paid') paid_total");$fs->execute(['t'=>$ticket['tenant_id'],'t2'=>$ticket['tenant_id'],'t3'=>$ticket['tenant_id']]);$financialSummary=$fs->fetch();}}?>
<?php if($billingRequest&&$billingRequest['request_type']==='account_deletion'):?><div class="card mb-4 border-danger"><div class="card-body"><div class="eyebrow">Solicitação administrativa</div><h2 class="h5">Exclusão/inativação da conta</h2><p>Prazo para análise: <strong><?=date('d/m/Y H:i',strtotime($billingRequest['deadline_at']))?></strong></p><div class="row g-2 mb-3"><div class="col-md-4"><div class="p-3 rounded bg-light">Faturas vencidas<br><strong><?=(int)($financialSummary['overdue_invoices']??0)?></strong></div></div><div class="col-md-4"><div class="p-3 rounded bg-light">Pagamentos pendentes<br><strong><?=(int)($financialSummary['pending_payments']??0)?></strong></div></div><div class="col-md-4"><div class="p-3 rounded bg-light">Total pago<br><strong>R$ <?=number_format((float)($financialSummary['paid_total']??0),2,',','.')?></strong></div></div></div><?php if($billingRequest['status']==='pending'&&(\App\Core\Auth::user()['role']??'')==='master'):?><form method="post" action="/master/solicitacoes-financeiras/<?=(int)$billingRequest['id']?>/aprovar-exclusao" onsubmit="return confirm('Confirma o cancelamento da cobrança e a inativação da empresa e de todos os usuários?')"><?php echo \App\Core\CSRF::field();?><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="financial_confirmed" value="1" required> Conferi pagamentos, faturas e situação financeira desta empresa.</label><button class="btn btn-danger">Aprovar e inativar conta</button></form><?php else:?><span class="badge text-bg-secondary">Situação: <?=htmlspecialchars($billingRequest['status'])?></span><?php endif;?></div></div><?php endif;?>
<?php if($billingRequest&&$billingRequest['request_type']==='invoice'):?><div class="card mb-4 border-primary"><div class="card-body"><div class="eyebrow">Solicitação financeira</div><h2 class="h5">Enviar nota fiscal</h2><p>Referência: <strong><?=htmlspecialchars(date('m/Y',strtotime($billingRequest['reference_period'].'-01')))?></strong></p><?php if($billingRequest['status']==='pending'&&(\App\Core\Auth::user()['role']??'')==='master'):?><form method="post" enctype="multipart/form-data" action="/master/solicitacoes-financeiras/<?=(int)$billingRequest['id']?>/enviar-nota"><?php echo \App\Core\CSRF::field();?><label class="form-label">Nota fiscal em PDF (até 10 MB)</label><input class="form-control" type="file" name="invoice_pdf" accept="application/pdf,.pdf" required><button class="btn btn-primary mt-3">Enviar PDF e concluir solicitação</button></form><?php else:?><span class="badge text-bg-success">Nota fiscal processada</span><?php endif;?></div></div><?php endif;?>
<?php if($platform&&($ticket['assigned_to']??null)):?><div class="alert alert-info"><strong>Responsável designado:</strong> usuário #<?=(int)$ticket['assigned_to']?></div><?php endif;?>
<?php if((\App\Core\Auth::user()['role']??'')==='master'):?><div class="card mb-4"><div class="card-body"><div class="eyebrow">Distribuição do suporte</div><h2 class="h5">Designar responsável</h2><form class="row g-2" method="post" action="/support/<?=(int)$ticket['id']?>/assign"><?php echo \App\Core\CSRF::field();?><div class="col-md-8"><select class="form-select" name="assigned_to"><option value="">Sem responsável</option><?php foreach($assignees as $person):?><option value="<?=(int)$person['id']?>" <?=((int)($ticket['assigned_to']??0)===(int)$person['id'])?'selected':''?>><?=htmlspecialchars($person['name'])?> — <?=$person['role_slug']==='commercial'?'Comercial + Suporte':'Suporte'?></option><?php endforeach;?></select></div><div class="col-md-4"><button class="btn btn-primary w-100">Designar chamado</button></div></form></div></div><?php endif;?>
<?php require __DIR__.'/show.php'; ?>
